function getNestedEntries(obj, path) {
    // Split the path into individual keys
    const parts = path.split('.');

    let currentObj = obj;
    for (let i = 0; i < parts.length - 1; i++) {
        const key = parts[i];

        if (!currentObj || !(key in currentObj)) {
            return []; // Return empty array if any key or value does not exist
        }

        currentObj = currentObj[key];
    }

    // If we reach the last part of the path, add it to the result
    return [currentObj[parts[parts.length - 1]]];
}

